{
  "commonPhenomenon": "支付通道已确认成功，但平台因未收到或尚未处理异步通知而处于等待状态。",
  "facts": [
    {
      "statement": "付款已由通道确认，平台仍等候异步通知更新状态。",
      "evidenceIds": [
        "E-011"
      ]
    }
  ],
  "differences": [
    {
      "description": "通道侧显示支付成功，而平台侧资金状态未同步更新为成功，存在状态不一致。",
      "evidenceIds": [
        "E-011"
      ]
    }
  ],
  "possibleExplanations": [
    {
      "hypothesis": "支付成功回调缺失：通道发送了成功通知，但因网络、验签或处理失败导致平台未接收或未处理。",
      "evidenceIds": [
        "E-011"
      ],
      "verification": "需比对通道支付时间、回调投递记录、平台入口访问日志和商户通知应答，确认是否缺少任一侧记录以区分未投递、网络失败、验签失败或处理失败。"
    },
    {
      "hypothesis": "平台与通道支付终态冲突：由于旧快照、状态映射差异或时区问题，导致观察到表面上的状态不同步。",
      "evidenceIds": [
        "E-011"
      ],
      "verification": "需先确认商户订单号、通道交易号和商户号都指向同一交易；比较状态采集时间、时区、来源及通道状态映射；查看回调、查单和人工操作审计。"
    },
    {
      "hypothesis": "关单后收到支付成功通知：平台可能误判或提前关单，随后收到迟到的成功通知。",
      "evidenceIds": [
        "E-011"
      ],
      "verification": "需按同一订单核对关单请求、通道对关单的应答、通道实际支付时间、通知生成时间和平台接收时间，并通过可信只读查单确认当前资金结果。"
    }
  ],
  "checkSteps": [
    "用商户订单号和通道交易号确认是同一笔交易。",
    "比对通道支付时间、回调投递记录、平台入口访问日志和商户通知应答。",
    "检查时确认日志时间范围、时区与保留期限。",
    "若缺少任一侧记录，先补齐对应证据再区分未投递、网络失败、验签失败或处理失败。",
    "通过可信只读查单确认当前资金结果。",
    "交由有权限的人员按业务流程复核后续处理。"
  ],
  "missingInformation": [
    "通道具体的回调投递记录及状态。",
    "平台侧接收回调的入口访问日志。",
    "商户侧收到的通知应答记录。",
    "各系统间的时间戳时区信息。",
    "通道交易号的详细映射关系。"
  ],
  "knowledgeCitations": [
    "lost-callback",
    "terminal-conflict",
    "late-success-after-close"
  ],
  "knowledgeOmissionReason": null
}
